def dedupe_certificate_serials(apps, schema_editor):
    """Attribue un numéro unique aux certificats avant la contrainte UNIQUE.

    Les anciennes versions calculaient ``Max(serial) + 1`` sans verrou :
    deux créations simultanées pouvaient obtenir le même numéro. On répare
    ici les éventuels doublons avant d'ajouter la contrainte.
    """
