    used = set()
    next_serial = 1

    for certificate in Certificate.objects.order_by('issued_at', 'pk'):
        serial = certificate.serial
        if serial and serial not in used:
            used.add(serial)
            next_serial = max(next_serial, serial + 1)
            continue

        while next_serial in used:
            next_serial += 1
        certificate.serial = next_serial
        certificate.save(update_fields=['serial'])
        used.add(next_serial)
        next_serial += 1


